// First-party examples, generated by the same native recipes used by the editor.
// Run: node --experimental-strip-types scripts/build-structural-overview.mjs
import {mkdirSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {componentRecipes,buildRecipe} from '../src/data/recipes.ts';
import {exportSceneSvg} from '../src/core/svg.ts';

const selected=process.argv.find(arg=>arg.startsWith('--ids='))?.slice(6).split(',');
const outputName=process.argv.find(arg=>arg.startsWith('--output='))?.slice(9)??'ppt-structure-overview.svg';
if(!/^[a-zA-Z0-9_-]+\.svg$/.test(outputName))throw new Error('Output must be an SVG basename');
const output=fileURLToPath(new URL(`../docs/research/assets/${outputName}`,import.meta.url));
const recipes=componentRecipes.filter(recipe=>recipe.category==='structure'&&(!selected||selected.includes(recipe.id)));
if(!recipes.length||selected?.some(id=>!recipes.some(recipe=>recipe.id===id)))throw new Error('Unknown structural recipe selection');
const columns=recipes.length<=4?2:3,rows=Math.ceil(recipes.length/columns),width=32+columns*592,height=140+rows*444+12;
const panels=recipes.map((recipe,index)=>{
  const figure=buildRecipe(recipe.id,recipe.defaults).figure,root=figure.containers[0],x=32+(index%columns)*592,y=140+Math.floor(index/columns)*444;
  const scene=exportSceneSvg(figure,{x:-8,y:-8,width:root.width+16,height:root.height+16},532,344)
    .replace('<svg ',`<svg x="${x+14}" y="${y+62}" `)
    .replace(/ id="([^"]+)"/g,` id="example-${index}-$1"`).replace(/url\(#/g,`url(#example-${index}-`);
  return `<rect x="${x}" y="${y}" width="560" height="424" rx="14" fill="#ffffff" stroke="#dce4ed"/>
<text x="${x+22}" y="${y+30}" font-size="21" font-weight="600" fill="#243247">${recipe.name}</text>
<text x="${x+22}" y="${y+51}" font-size="12" fill="#64748b">${recipe.id}</text>${scene}`;
});
const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" font-family="Inter, MiSans, sans-serif">
<title>FastFigure 论文结构图原生配方</title><rect width="${width}" height="${height}" fill="#f5f7fa"/>
<text x="38" y="58" font-size="30" font-weight="700" fill="#1e293b">论文主图：${recipes.length} 类结构表达</text>
<text x="38" y="96" font-size="17" fill="#536176">原生图元 · 独立改字与编辑 · 参数更新 · 素材保存 · 助手复用</text>
${panels.join('\n')}
<text x="38" y="${height-20}" font-size="13" fill="#64748b">FastPPT / 论文原文结构研究 · FastFigure 原生独立示意 · 来源与语义限制随配方保存。</text></svg>`;
mkdirSync(new URL('../docs/research/assets/',import.meta.url),{recursive:true});writeFileSync(output,svg);console.log(output);
